import 'package:dio/dio.dart';
import 'dart:convert';
class RouterOsRestApi {final Dio _dio;RouterOsRestApi(String baseUrl,String username,String password):_dio=Dio(BaseOptions(baseUrl:baseUrl,connectTimeout:const Duration(seconds:5),receiveTimeout:const Duration(seconds:7),headers:{'Authorization':'Basic ${base64Encode(utf8.encode('$username:$password'))}'},validateStatus:(s)=>s!=null&&s<500));Future<List<dynamic>> getList(String path) async {final r=await _dio.get(path);if(r.statusCode==401||r.statusCode==403)throw Exception('بيانات الدخول أو صلاحيات API غير صحيحة');if(r.statusCode!=200)throw Exception('RouterOS REST HTTP ${r.statusCode}');return r.data is List?r.data as List<dynamic>:[];}Future<Map<String,dynamic>> resource() async {final a=await getList('/rest/system/resource');return a.isEmpty?{}:Map<String,dynamic>.from(a.first as Map);}Future<List<dynamic>> hotspotUsers()=>getList('/rest/ip/hotspot/user');Future<List<dynamic>> pppUsers()=>getList('/rest/ppp/secret');}
